#!/usr/bin/env node
/**
 * Tests for the question judge and the guidance to the reviewers in workflows/dev-loop.js: before a question stalls, a
 * Sonnet agent may point at the owner's own words; the code accepts the answer only when its quote is literally in the
 * owner text. Resolution guidance reaches the reviewers from the round after it. Harness: tools/dev-loop.harness.mjs.
 *
 * Generated by Claude Code at the user's request.
 */

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { run, ARGS_M, review, finding, impl, gate } from './dev-loop.harness.mjs';

const question = { text: 'Who owns the data?', default: 'the tenant', why: 'unsaid', reversible: false, axis: 'data' };
const REQUEST = 'Fix the lookup. The tenant owns the data, nobody else.';
const ARGS = { ...ARGS_M, request: REQUEST };
const green = (extra = {}) => impl({ gate: gate('green'), ...extra });
const judging = (judgment) => ({ judge: () => ({ judgments: [{ text: question.text, ...judgment }] }) });
const judgeCalls = (calls) => calls.filter(c => c.opts.label?.startsWith('question judge'));

test('given a question the request already answers, when the judge quotes the request literally, then the loop goes on with the answer', async () => {
  // Given
  const impls = [green({ questions: [question] }), green()];
  // When
  const { out, calls } = await run(ARGS, [], impls, judging({ status: 'answered', answer: 'the tenant', quote: 'The tenant owns the data' }));
  // Then
  assert.notEqual(out.stall?.why, 'question');
  assert.equal(judgeCalls(calls)[0].opts.model, 'sonnet');
  assert.deepEqual(out.judged.map(j => [j.round, j.text, j.answer]), [[0, question.text, 'The tenant owns the data, nobody else.']]);
});

test('given a judge that invents a quote, when the code checks it against the owner text, then the question still stalls', async () => {
  // Given
  const impls = [green({ questions: [question] })];
  // When
  const { out } = await run(ARGS, [], impls, judging({ status: 'answered', answer: 'the vendor', quote: 'the vendor owns the data' }));
  // Then
  assert.equal(out.stall.why, 'question');
  assert.deepEqual(out.stall.questions.map(q => q.text), [question.text]);
  assert.equal(out.judged, undefined);
});

test('given a judge that says open, when it answers, then the question stalls for the owner', async () => {
  // Given
  const impls = [green({ questions: [question] })];
  // When
  const { out } = await run(ARGS, [], impls, judging({ status: 'open' }));
  // Then
  assert.equal(out.stall.why, 'question');
});

test('given no owner text at all, when a question comes up, then no judge is called', async () => {
  // Given
  const impls = [green({ questions: [question] })];
  // When
  const { out, calls } = await run(ARGS_M, [], impls);
  // Then
  assert.equal(out.stall.why, 'question');
  assert.equal(judgeCalls(calls).length, 0);
});

test('given an owner guidance at round 1, when round 2 starts, then its reviewers get the guidance', async () => {
  // Given
  const queue = [review([], [finding({ id: 'F1' })]), review([{ id: 'F1', status: 'closed' }])];
  const resolutions = [{ round: 1, guidance: 'keep the newest-first sort' }];
  // When
  const { calls } = await run({ ...ARGS_M, resolutions }, queue, [green(), green()]);
  // Then
  const readers = calls.filter(c => /^reviewer \S+ · round \d+/.test(c.opts.label ?? ''));
  const r1 = readers.filter(c => / round 1(?!\d)/.test(c.opts.label));
  const r2 = readers.filter(c => / round 2(?!\d)/.test(c.opts.label));
  assert.ok(r1.length > 0 && r1.every(c => !c.prompt.includes('keep the newest-first sort')));
  assert.ok(r2.length > 0 && r2.every(c => c.prompt.includes('keep the newest-first sort')));
});

test('given a judged answer handed back in the resolutions, when the run resumes, then the question is answered with no judge call and no stall', async () => {
  // Given
  const resolutions = [{ round: 0, answers: [{ text: question.text, answer: 'the tenant', quote: 'The tenant owns the data', judged: true }] }];
  const impls = [green({ questions: [question] }), green()];
  // When
  const { out, calls } = await run({ ...ARGS, resolutions }, [], impls);
  // Then
  assert.notEqual(out.stall?.why, 'question');
  assert.equal(judgeCalls(calls).length, 0);
});

test('given the judge answered a question, when the loop stalls later, then the result hands the judged answer back for the resume', async () => {
  // Given
  const impls = [green({ questions: [question] }), green()];
  // When
  const { out } = await run({ ...ARGS, resolutions: [] }, [], impls, judging({ status: 'answered', answer: 'the tenant', quote: 'The tenant owns the data' }));
  // Then
  assert.equal(out.judged[0].judged, true);
  assert.equal(out.judged[0].quote, 'The tenant owns the data');
});
